from h import build
R=[
(3501639,"Crumble de poulet et de légumes",
"Un repas sain avec une petite quantité de parmesan et de noix pour apporter du croquant sans trop de phosphate par portion. Le fait de faire bouillir les légumes au préalable garde la teneur en potassium faible.",
"6",None,
["2 patates douces (environ 120 g), pelées et coupées en dés","300 g de céleri-rave, pelé et coupé en dés","2 carottes (environ 120 g), pelées et coupées en dés","1 poireau (environ 70 g), tranché","150 g de petits pois surgelés","1 cuillère à café d'huile d'olive","400 g de poitrines de poulet sans peau, coupées en dés","400 ml de bouillon de légumes à faible teneur en sel","200 ml de crème fraîche demi-grasse","2 cuillères à soupe de farine ordinaire","1 cuillère à soupe de moutarde à l'ancienne","1 cuillère à café de sauge séchée",["Garniture crumble","150 g de beurre non salé"],["Garniture crumble","200 g de farine ordinaire"],["Garniture crumble","25 g d'amandes moulues"],["Garniture crumble","40 g de parmesan, râpé"],["Garniture crumble","25 g d'amandes effilées"]],
["Chauffez le four à 190 °C / chaleur tournante 170 °C / thermostat gaz 5 et portez une grande casserole d'eau à ébullition. Pelez et coupez en dés le céleri-rave, les patates douces et les carottes. Parez, nettoyez et tranchez les poireaux. Coupez le poulet en dés de taille égale.","Ajoutez les patates douces et les légumes dans la casserole d'eau bouillante. Faites bouillir 10 à 15 minutes, égouttez et jetez l'eau. Faites chauffer l'huile d'olive dans une poêle et faites cuire le poulet.","Ajoutez les légumes égouttés au poulet et ajoutez le bouillon de légumes. Laissez mijoter à feu doux 5 minutes.","Mélangez la crème fraîche avec la farine et la moutarde. Incorporez au poulet et aux légumes jusqu'à ce que le tout épaississe, puis ajoutez la sauge. Retirez du feu.","Pour le crumble, utilisez le bout des doigts pour incorporer le beurre, la farine et les amandes moulues jusqu'à obtenir une texture de chapelure. Râpez et incorporez le parmesan et ajoutez les amandes effilées.","Versez à la cuillère la garniture de poulet et de légumes dans un plat allant au four et parsemez le crumble sur le dessus. Pour la cuisson, faites cuire au four 30 à 35 minutes jusqu'à ce que le dessus soit doré."],
[["Note du chef","Ce crumble salé est délicieux avec sa garniture crémeuse de poulet et de légumes et son dessus croustillant et fromagé. Excellent pour un repas en famille et se congèle bien à la maison."],["Glucides","Les glucides de ce plat proviennent principalement de la patate douce et de la farine. Les valeurs en glucides sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Les noix sont riches à la fois en phosphate et en potassium, mais dans les quantités utilisées ici, les amandes peuvent tout de même être incluses pour une garniture croustillante. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat. Faire bouillir les légumes et jeter l'eau aide à éliminer une partie du potassium. Le céleri-rave est souvent évité à cause de sa forte teneur en potassium, mais lorsqu'il est bouilli et utilisé dans les quantités indiquées, il peut être inclus dans un régime pauvre en potassium."],["Protéines","Le poulet de ce plat fournit des protéines et en fait un bon choix si vous êtes sous dialyse. Pour les personnes à qui l'on a conseillé de réduire leur apport en protéines, pourquoi ne pas essayer la recette de crumble aux légumes."],["Sans gluten","Utilisez de la farine sans gluten dans le crumble et de la fécule de maïs dans la sauce."],["Option plus saine","Aucun sel n'est ajouté dans cette recette, mais elle est légèrement au-dessus de la limite pour être classée comme plat faible en sel. Pour réduire la teneur en matières grasses de ce plat, utilisez une margarine faible en gras à la place du beurre."],["Conservation","Cette recette peut être congelée avant la cuisson au four en l'enveloppant de pellicule plastique, puis de papier d'aluminium. Pour la décongeler, laissez-la dégeler au réfrigérateur pendant la nuit et faites cuire 30 à 35 minutes comme ci-dessus."],["Astuces","Essayez de râper le beurre directement sorti du réfrigérateur. C'est une façon rapide et facile d'obtenir des miettes parfaites en un rien de temps !"]],
[]),
(3502648,"Bortsch",
"Une version faible en potassium d'une recette traditionnelle d'Europe de l'Est.",
"4",None,
["400 g de betterave, pelée et tranchée","300 g de carottes, pelées et coupées en rondelles","2 gousses d'ail, pelées et finement tranchées","90 g d'échalotes, finement tranchées","1 feuille de laurier","1 cuillère à café de graines de coriandre","3 clous de girofle","Une pincée à ½ cuillère à café de piment de Cayenne (selon votre goût pour le piquant et la force de votre piment)","1 cuillère à soupe de sucre extra-fin","1 cuillère à soupe d'huile d'olive extra vierge","2 cuillères à café de vinaigre de vin rouge",["Pour servir","4 petits pains"],["Pour servir","1 cuillère à soupe d'huile d'olive"],["Pour servir","4 œufs"],["Pour servir","250 g de yogourt entier"],["Pour servir","Feuilles de quelques brins d'aneth frais, hachées, ou quelques brins de ciboulette hachés"]],
["Portez une casserole moyenne d'eau à ébullition et ajoutez la betterave tranchée, les carottes et les œufs. Faites bouillir cinq minutes, puis égouttez et mettez les œufs durs de côté pour les laisser refroidir. Une fois refroidis, retirez la coquille et tranchez les œufs pour les utiliser plus tard. Mettez la betterave et la carotte blanchies dans une grande casserole.","Ajoutez 500 ml d'eau froide dans la casserole, avec l'ail, les échalotes, la feuille de laurier, les graines de coriandre, les clous de girofle, le piment de Cayenne, le sucre, l'huile d'olive et la moitié du vinaigre. Couvrez et portez à ébullition, puis réduisez à feu moyen-doux. Laissez mijoter 20 minutes ou jusqu'à ce que la betterave et la carotte soient tendres.","Retirez la feuille de laurier, puis réduisez la soupe en purée au mélangeur. Pour la rendre ultra lisse, vous pouvez la passer au tamis dans un grand bol ou un pichet, mais ce n'est peut-être pas nécessaire. Goûtez pour voir si elle a besoin de poivre noir ou de vinaigre supplémentaire.","Ce plat peut être servi chaud ou froid. Si vous le servez chaud, réchauffez-le à feu moyen dans une casserole. Avant de servir, incorporez le yogourt en fouettant et garnissez d'aneth ou de ciboulette hachés, d'un filet d'huile d'olive et des œufs durs tranchés. Servez avec un petit pain en accompagnement."],
[["Note du chef","Voici une soupe délicieuse et saine qui peut être servie chaude ou froide. Elle est encore meilleure un jour ou deux après sa préparation."],["Glucides","Les petits pains sont la principale source de glucides de ce repas. La valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","La principale source de potassium de ce plat est la betterave, mais les quantités utilisées dans la recette ont été maintenues dans une plage qui garantit que l'ensemble du repas est faible en potassium.\nCe plat est faible en phosphate, mais il en contient tout de même un peu. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Ce plat est faible en protéines, ce qui le rend adapté aux personnes à qui l'on a conseillé de suivre un régime à teneur réduite en protéines. Il pourrait donc ne pas convenir aux personnes sous dialyse. Si on vous a conseillé de manger plus de protéines et que vous ne suivez pas un régime végétarien/végane, vous pourriez remplacer l'œuf par 250 g de poulet cuit effiloché."],["Sans gluten","Servez avec des petits pains sans gluten."],["Végane","Utilisez un yogourt sans produits laitiers ou de la crème sure végane et remplacez les œufs par une boîte de pois chiches égouttés."],["Option plus saine","Ce plat est déjà sain, mais vous pourriez utiliser un yogourt faible en gras pour garder une faible teneur en matières grasses et un petit pain de blé entier pour augmenter les fibres."],["Conservation","Le bortsch se conserve jusqu'à trois jours au réfrigérateur ou jusqu'à trois mois au congélateur (avant d'ajouter le yogourt)."],["Gestion des liquides","Si on vous a conseillé de suivre une restriction liquidienne, n'oubliez pas d'inclure cette soupe dans votre allocation quotidienne de liquides."]],
[]),
(3511962,"Pain aux bananes",
"Avec une seule banane, cette recette est une délicieuse option faible en potassium et faible en sel à savourer comme gâterie ou comme dessert.",
"10",None,
["1 banane mûre (environ 120 g sans la pelure)","1 œuf","½ cuillère à café d'extrait de vanille","100 g de beurre non salé, ramolli","60 g de cassonade claire","120 g de farine ordinaire sans gluten","1 cuillère à café de bicarbonate de soude","1 cuillère à café de crème de tartre","60 g de canneberges séchées"],
["Préchauffez le four à 190 °C / thermostat gaz 5. Graissez et chemisez un moule à pain de 450 g.","Battez l'œuf et écrasez-le avec la banane et l'extrait de vanille.","Dans un autre bol, travaillez le beurre et le sucre en crème.","Ajoutez le mélange de banane au mélange de beurre et de sucre et battez ensemble.","Incorporez la farine, le bicarbonate de soude, la crème de tartre et les canneberges et mélangez bien.","Versez dans le moule préparé et faites cuire 40 à 45 minutes ou jusqu'à ce qu'une brochette en ressorte propre. Laissez refroidir dans le moule cinq minutes avant de le démouler sur une grille pour qu'il refroidisse complètement."],
[["Note du chef","Le pain aux bananes est un choix simple et réconfortant. Cette version qui se congèle bien est aussi sans gluten."],["Glucides","Les principales sources de glucides de cette recette sont la farine, le sucre, la banane et les canneberges. Les valeurs en glucides sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","La banane est un fruit riche en potassium, mais seulement 1 banane est utilisée pour 10 portions, ce qui garde cette recette faible en potassium dans l'ensemble. Par conséquent, une portion peut être savourée à l'occasion dans le cadre d'un régime pauvre en potassium.\nCette recette contient du phosphate qui est principalement fourni par les agents levants. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Ce pain aux bananes est faible en protéines et peut être savouré lors d'occasions spéciales dans le cadre d'un régime à teneur réduite en protéines."],["Option plus saine","Le sucre de cette recette a déjà été réduit, mais si vous le trouvez trop sucré, vous pourriez envisager de le réduire davantage. Vous pouvez aussi utiliser une tartinade faible en gras à la place du beurre non salé, ce qui réduira la teneur en matières grasses."],["Option plus économique","Cette recette est relativement peu coûteuse, mais vous pourriez envisager d'utiliser du sucre extra-fin ordinaire à la place de la cassonade, ce qui pourrait vous faire économiser une petite somme."],["Conservation","Une fois refroidi, il est préférable de trancher le pain aux bananes en 10 portions et de le conserver dans un contenant hermétique jusqu'à 3 jours. Si vous ne le partagez pas avec vos amis et votre famille, vous pouvez envelopper les tranches individuellement et les congeler jusqu'à 3 mois. Laissez décongeler complètement avant de manger."]],
[]),
(3560541,"Chaussons au brie et aux canneberges",
"Cette collation faible en potassium est une belle gâterie des fêtes.",
"18",None,
["12 feuilles de pâte phyllo prête à dérouler 100 g de beurre non salé 250 g de brie 75 g de sauce aux canneberges 50 g de noix hachées Un peu de graines de pavot (facultatif)"],
["Chauffez le four à 220 °C / thermostat gaz 7. Faites fondre le beurre et badigeonnez-en chaque feuille de phyllo, puis empilez deux feuilles de phyllo l'une sur l'autre, les grands côtés face à vous.","Coupez le brie en 18 gros bâtonnets et espacez-les sur le bas de la feuille de phyllo. Garnissez chaque bâtonnet de 1 cuillère à café de sauce aux canneberges, puis saupoudrez de quelques noix hachées. Coupez la pâte phyllo en longues colonnes.","Roulez la pâte phyllo à partir du bas. Coupez chaque rouleau en trois chaussons et tordez les extrémités de chaque chausson pour sceller. Badigeonnez les chaussons de beurre supplémentaire et saupoudrez de graines de pavot.","Répétez les étapes 2 à 4 en utilisant tous les ingrédients. Faites cuire au four 10 minutes. Une fois dorés, sortez du four et laissez refroidir légèrement avant de servir."],
[["Note du chef","Ces savoureux chaussons de pâte phyllo constituent une gâterie raffinée. Garnis de brie crémeux, de canneberges sucrées et de noix croquantes."],["Glucides","La pâte phyllo et la sauce aux canneberges sont les principales sources de glucides de cette collation. La valeur en glucides est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Les ingrédients de cette recette sont faibles en potassium. C'est une collation qui peut être savourée dans le cadre d'un régime pauvre en potassium, en petites quantités, pour une occasion spéciale. Le phosphate de cette recette est fourni principalement par le brie et, en petite quantité, par les noix. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec cette collation et évitez d'en manger trop."],["Protéines","Les protéines de cette recette sont fournies par le fromage et les noix."],["Sans gluten","Utilisez de la pâte phyllo sans gluten."],["Végétarien","Vérifiez le fromage que vous utilisez pour vous assurer qu'il est végétarien."],["Végane","Utilisez de la pâte végane et un fromage végane approprié."],["Option plus saine","Cette collation est destinée aux occasions spéciales et conviendrait particulièrement bien au temps de Noël; elle ne doit toutefois être consommée qu'avec modération. Il peut aussi être judicieux de réduire la recette de moitié pour de petits rassemblements ou de petits ménages."],["Option plus économique","Les ingrédients de cette recette sont relativement peu coûteux; toutefois, pour réduire le coût tout en conservant le goût, vous pourriez omettre les noix et/ou les graines de pavot."],["Conservation","Ces chaussons se dégustent de préférence fraîchement cuits; toutefois, pour les conserver, laissez-les refroidir, mettez-les dans un contenant hermétique et réfrigérez-les jusqu'à 3 jours."]],
[]),
(3562881,"Tacos aux haricots noirs",
"Ces tacos d'inspiration mexicaine sont riches en fibres et très nourrissants. Ce plat sain est faible en phosphate, en potassium et en sel.",
"4",None,
["1 oignon rouge, coupé en fines lanières","1 poivron rouge, coupé en fines lanières","2 cuillères à soupe d'huile d'olive","1 boîte de 200 g de maïs dans l'eau","½ cuillère à café de paprika fumé","1 boîte de 400 g de haricots noirs dans l'eau","2 gousses d'ail, râpées","½ cuillère à café de cannelle moulue","½ cuillère à café de cumin moulu","Poivre noir","50 g de tomates cerises, coupées en quartiers","1 oignon vert, finement tranché","5 g de coriandre fraîche, hachée","¼ cuillère à café de sauce piquante","2 limes","1 petit avocat, mûr","8 mini tortillas","1 piment frais, finement tranché (facultatif)"],
["Préchauffez le four à 180 °C / 160 °C chaleur tournante / thermostat gaz 3 et chemisez deux plaques de cuisson de papier sulfurisé. Mettez l'oignon tranché et le poivron rouge dans un bol. Ajoutez une cuillère à soupe d'huile, assaisonnez de poivre et mélangez. Étalez les légumes sur l'une des plaques.","Égouttez le maïs et épongez-le. Versez-le dans un bol, assaisonnez de poivre et de paprika fumé et mélangez. Étalez le maïs sur la deuxième plaque de cuisson. Mettez les deux plaques au four 25 à 30 minutes, remuez à mi-cuisson, puis laissez refroidir.","Égouttez et rincez les haricots, versez-les dans un bol et écrasez-les à la fourchette. Faites chauffer l'huile dans une casserole à feu moyen et ajoutez l'ail. Remuez 30 secondes, puis ajoutez la cannelle, le cumin, le poivre noir, les haricots noirs et un peu d'eau au besoin.","Faites cuire doucement trois minutes, puis retirez du feu. Pour la salsa, mettez la sauce piquante dans un bol et pressez-y le jus de ½ lime, mélangez. Ajoutez les tomates, les oignons verts et les feuilles de coriandre et mélangez de nouveau.","Pour le guacamole, coupez l'avocat en deux et retirez délicatement le noyau. Mettez toute la chair de l'avocat dans un autre bol, pressez-y le jus d'une lime et écrasez à la fourchette jusqu'à obtenir une texture crémeuse. Réservez jusqu'au moment de servir.","Étalez les tortillas. Garnissez chacune d'une couche de haricots noirs, de légumes et de maïs et ajoutez un peu de salsa et de guacamole. Servez deux tacos par personne, avec un quartier de lime (et le piment et de la coriandre hachée supplémentaire si vous le désirez)."],
[["Note du chef","Avec des légumes rôtis, des haricots noirs et une salsa et un guacamole adaptés aux reins, ces tacos font un lunch ou un souper végane rapide."],["Glucides","La principale source de glucides de ce plat provient des tortillas. La valeur en glucides de ce plat est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Malgré l'utilisation de certains ingrédients riches en potassium, par exemple les tomates cerises et l'avocat, si vous respectez les quantités indiquées et les tailles de portion fournies dans cette recette, ce plat est faible en potassium dans l'ensemble. Les haricots noirs contiennent du phosphate, mais la portion utilisée dans cette recette maintient une faible teneur totale en phosphate. Si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Cette recette est faible en protéines, ce qui en fait un repas approprié pour les personnes à qui l'on a conseillé de suivre un régime pauvre en protéines."],["Sans gluten","Utilisez des tortillas sans gluten."],["Option plus saine","Ce plat est sain, car il est naturellement faible en sel, en matières grasses et en sucre et riche en fibres. Toutefois, il est préférable de vérifier les étiquettes lors de l'achat des tortillas et de vous assurer d'acheter celles dont la teneur en sel est la plus faible."],["Option plus économique","Ce plat est relativement peu coûteux. Toutefois, vous pouvez acheter du jus de lime en bouteille pour éviter tout gaspillage alimentaire."],["Conservation","Tous les éléments de ce plat peuvent être préparés à l'avance. Conservez les légumes, les haricots noirs, la salsa et le guacamole séparément dans des contenants hermétiques, gardez-les au réfrigérateur et consommez-les dans les 3 jours. Assemblez les tacos juste avant de servir."]],
[]),
(3563134,"Cari de poulet et de légumes",">","2",None,
["1 grosse/2 petites poitrines de poulet (200 g), sans peau et désossées, coupées en petits morceaux","50 ml de yogourt nature faible en gras","½ cuillère à café de piment rouge en poudre","2 cuillères à café de garam masala/poudre de cari","1 cuillère à café de curcuma","120 g de riz basmati, rincé","1 cuillère à soupe d'huile végétale","1 oignon, pelé et finement haché","½ boîte de tomates concassées (200 g)","½ pouce de gingembre, écrasé","2 gousses d'ail, écrasées","80 g de carottes, pelées et coupées en dés","40 g de haricots verts, coupés","30 g de petits pois verts surgelés","Une petite poignée de coriandre fraîche, grossièrement hachée."],
["Faites mariner les morceaux de poulet dans le yogourt, la poudre de piment, le garam masala et le curcuma pendant 30 minutes.","Lavez le riz, mettez-le dans une casserole avec le double d'eau, portez à ébullition, couvrez et réduisez le feu. Laissez mijoter 10 minutes jusqu'à ce qu'il soit cuit, en vérifiant s'il faut ajouter de l'eau.","Faites chauffer l'huile à feu moyen et faites revenir l'oignon jusqu'à ce qu'il soit brun clair.","Ajoutez les tomates, le gingembre et l'ail et faites revenir 1 à 2 minutes jusqu'à ce que les oignons et les tomates soient bien mélangés, puis ajoutez les légumes et faites revenir une minute.","Ajoutez le poulet mariné et remuez bien pour que le poulet se mélange à l'oignon, aux tomates et aux légumes. Réduisez à feu doux, couvrez et laissez cuire le poulet et les légumes 20 minutes.","Une fois le poulet cuit, ajoutez la coriandre fraîchement hachée et servez chaud avec le riz."],
[["Note du chef","Ce cari de style indien, riche en protéines, est parfait pour la cuisine en lots."],["Glucides","Le riz est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Malgré certains ingrédients riches en potassium, comme les tomates, cette recette est faible en potassium si vous respectez les quantités et les tailles de portion indiquées, et convient aux personnes à qui l'on a conseillé de réduire le potassium. Elle est aussi faible en phosphate, mais elle en contient un peu, principalement provenant du poulet; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est riche en protéines; elle convient donc aux personnes à qui l'on a conseillé de manger plus de protéines, comme celles sous dialyse. Si on vous a conseillé de manger moins de protéines, réduisez la quantité de poulet à 100 g, ou utilisez plutôt 400 g de pois chiches en conserve égouttés."],["Conservation","Conservez dans un contenant hermétique au réfrigérateur jusqu'à 2 jours, ou congelez (réchauffez bien)."],["Astuces","Ajouter 2 à 3 grains de poivre noir, 1 bâton de cannelle et 2 à 3 clous de girofle à l'huile avant d'ajouter les oignons rehausse la saveur."]],
[]),
]
